"use strict";
// A dependency that keeps the deprecated Buffer constructor.
exports.construct = function (value, encodingOrOffset, length) {
  if (length !== undefined) return new Buffer(value, encodingOrOffset, length);
  if (encodingOrOffset !== undefined) return new Buffer(value, encodingOrOffset);
  return new Buffer(value);
};
exports.call = function (value) {
  return Buffer(value);
};
exports.many = function (count) {
  let total = 0;
  for (let i = 0; i < count; i++) total += new Buffer(1).length;
  return total;
};
